#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

# The Sheet v5: Lisul's one-time setup (docs/sheet-v5.md, "Setup").
#
#   bash tools/sheet-v5-setup.sh
#
# Everything is already deployed. These are the steps only Lisul can take. Every secret goes
# straight into the Supabase dashboard: this script never sees one, and writes no .env. The only
# things it changes itself are the Vault URLs (not secrets) that switch each sync on, and one
# test fire of the morning task. Optional sources can be skipped and done on a later run.

REF=bmbsvvprpfdbvalnkowp
URL="https://$REF.supabase.co"
GCP="project=the-sheet-512218"
SECRETS_PAGE="https://supabase.com/dashboard/project/$REF/functions/secrets"
PLAN="https://lisul-elvi.com/plan/"
cd "$(dirname "$0")/.."

sb() { npx -y supabase@latest "$@"; }

# sql "query" runs one query on the live database and prints only its rows' values.
sql() { sb db query --remote="$REF" --yes "$1" 2>/dev/null | grep -oE '"[a-z_]+": [^,}]+' || true; }

# vault_url NAME FUNCTION adds the Vault URL that switches a sync job on, once.
vault_url() {
  sb db query --remote="$REF" --yes "select vault.create_secret('$URL/functions/v1/$2', '$1')
    where not exists (select 1 from vault.secrets where name = '$1')" >/dev/null 2>&1 \
    && printf '  %s✓ switched on%s %s (Vault %s)\n' "$GREEN" "$RESET" "$2" "$1" \
    || { SKIPPED+=("Vault URL $1 (docs/sheet-v5.md, Deploy step 7)"); warn "couldn't add $1; try again later"; }
}

run_wizard() {

TOTAL_STAGES=14

banner "The Sheet v5 setup"

# ── 1 ────────────────────────────────────────────────────────────────────
stage "Google Cloud: turn on the Calendar API"
say "The busy-time sync asks Google Calendar when you're free. Signed in as elvitigalalis@gmail.com:"
open_url "https://console.cloud.google.com/apis/library/calendar-json.googleapis.com?$GCP"
step "Check the project picker says \"The Sheet\" (the-sheet-512218)."
step "Click Enable. If it says \"Manage\", it's on already."
pause "Press Enter when it's enabled"

# ── 2 ────────────────────────────────────────────────────────────────────
stage "Google Cloud: add the calendar redirect"
open_url "https://console.cloud.google.com/auth/clients?$GCP"
step "Click the web client you use for mail (the one ending ...ja3maja4qom88...)."
step "Under Authorized redirect URIs, click Add URI and paste:"
say "    $URL/functions/v1/calendar-connect/callback"
step "Keep the mail-connect and Auth ones that are already there. Click Save."
pause "Press Enter when it's saved"

# ── 3 ────────────────────────────────────────────────────────────────────
stage "Google Cloud: allow the free/busy scope"
open_url "https://console.cloud.google.com/auth/scopes?$GCP"
step "Click Add or remove scopes."
step "Filter for calendar.freebusy and tick .../auth/calendar.freebusy"
say "    (\"See the availability on Google Calendars you have access to\")."
step "Click Update, then Save at the bottom."
pause "Press Enter when it's saved"

# ── 4 ────────────────────────────────────────────────────────────────────
stage "Google Cloud: publish the app"
say "In Testing, Google throws your sign-ins away every 7 days. In production they last."
open_url "https://console.cloud.google.com/auth/audience?$GCP"
step "Under Publishing status, click Publish app, then Confirm."
note "It's still only for you. Google will show \"Google hasn't verified this app\" when you"
note "connect: click Advanced → Go to The Sheet (unsafe). That's expected for a personal app."
note "If it's already \"In production\", skip this."
pause "Press Enter when it's published"

# ── 5 ────────────────────────────────────────────────────────────────────
stage "/plan: connect your calendar"
open_url "$PLAN"
step "Click ••• (top right) → Settings → Calendar → Connect."
step "Pick elvitigalalis@gmail.com, get past the unverified screen, and allow"
say "    \"See the availability on Google Calendars\"."
step "You land back on /plan, and Settings shows Calendar connected."
pause "Press Enter when it says connected"
if [[ "$(sql "select count(*) as n from calendar_account")" =~ \"n\":\ ([1-9]) ]]; then
  vault_url sheet_busy_url busy-sync
else
  SKIPPED+=("Calendar not connected yet: re-run this script after Connect")
  warn "The calendar isn't connected yet, so the busy sync stays off. Re-run this script later."
fi
pause

# ── 6 ────────────────────────────────────────────────────────────────────
stage "Supabase: the mail sync's salt"
say "The mail sync remembers who you've written to as salted hashes, never addresses."
say "The salt is one random value, set once and NEVER changed (changing it forgets everyone)."
step "Copy a fresh one to your clipboard (it isn't shown here):"
say "    openssl rand -hex 32 | tr -d '\\n' | pbcopy"
if confirm "Copy it now for you?"; then openssl rand -hex 32 | tr -d '\n' | pbcopy; say "  Copied."; fi
open_url "$SECRETS_PAGE"
step "Add a secret named SHEET_SENDER_SALT, paste the value, Save."
note "If SHEET_SENDER_SALT is already in the list, leave it alone."
if confirm "Is SHEET_SENDER_SALT saved?"; then
  vault_url sheet_mail_url mail-sync
else
  SKIPPED+=("SHEET_SENDER_SALT, then re-run for the mail sync")
fi
pause

# ── 7 ────────────────────────────────────────────────────────────────────
stage "GitHub (optional): your PRs and issues"
WORK=0
if confirm "Set up GitHub now?"; then
  open_url "https://github.com/settings/personal-access-tokens/new"
  step "Name it \"The Sheet\", expiry 1 year."
  step "Resource owner: the org whose PRs you want (one token per owner; pick the main one)."
  step "Repository access: All repositories."
  step "Permissions → Repository: Pull requests Read-only, Issues Read-only (Metadata is automatic)."
  step "Generate, and copy the token (github_pat_...)."
  open_url "$SECRETS_PAGE"
  step "Add SHEET_GITHUB_TOKEN with that value. Save."
  open_url "$PLAN"
  step "••• → Settings → Feeds → GitHub orgs: type the org names, comma-separated. Save."
  confirm "Saved both?" && WORK=1 || SKIPPED+=("GitHub token and orgs")
else
  note "Skipped. Re-run the script any time to add it."
fi
pause

# ── 8 ────────────────────────────────────────────────────────────────────
stage "Jira (optional): your tickets"
if confirm "Set up Jira now?"; then
  open_url "https://id.atlassian.com/manage-profile/security/api-tokens"
  step "Create API token (a scoped one with read:jira-work if it offers scopes), name it"
  say "    \"The Sheet\", and copy it."
  open_url "$SECRETS_PAGE"
  step "Add three secrets, then Save:"
  say "    SHEET_JIRA_TOKEN  the token"
  say "    SHEET_JIRA_EMAIL  the email you sign in to Jira with"
  say "    SHEET_JIRA_SITE   your site, like name.atlassian.net"
  confirm "Saved all three?" && WORK=1 || SKIPPED+=("Jira secrets")
else
  note "Skipped."
fi
(( WORK )) && vault_url sheet_work_url work-sync
pause

# ── 9 ────────────────────────────────────────────────────────────────────
stage "Slack (optional): DMs and mentions"
if confirm "Set up Slack now?"; then
  say "Slack needs a tiny app of your own that only can search."
  open_url "https://api.slack.com/apps?new_app=1"
  step "Create New App → From scratch, name \"The Sheet\", pick the workspace."
  step "OAuth & Permissions → User Token Scopes → Add search:read. Nothing else."
  step "Install to Workspace (top of that page) → Allow."
  note "A team workspace may ask an admin to approve the app first."
  step "Copy the User OAuth Token (xoxp-...)."
  open_url "$SECRETS_PAGE"
  step "Add SHEET_SLACK_TOKEN with it. Save."
  if confirm "Saved?"; then vault_url sheet_slack_url slack-sync; else SKIPPED+=("Slack token"); fi
else
  note "Skipped."
fi
pause

# ── 10 ───────────────────────────────────────────────────────────────────
stage "Handshake and the academic calendar (optional)"
ICAL=0
if confirm "Set these up now?"; then
  say "Both are calendar subscription links (.ics or webcal://). Treat them like passwords."
  open_url "https://app.joinhandshake.com/"
  step "Handshake: find its calendar subscribe or sync link (look under your events or the"
  say "    calendar menu; the exact place moves). Copy it."
  open_url "https://www.stonybrook.edu/registrar/calendars/"
  step "Academic calendar: copy its Subscribe / iCal link, if it has one."
  open_url "$SECRETS_PAGE"
  step "Add whichever you found: SHEET_HANDSHAKE_ICS, SHEET_ACADEMIC_ICS. Save."
  confirm "Saved at least one?" && ICAL=1 || SKIPPED+=("Handshake / academic links")
else
  note "Skipped."
fi
(( ICAL )) && vault_url sheet_ical_url ical-sync
pause

# ── 11 ───────────────────────────────────────────────────────────────────
stage "Replans: one test fire"
say "Replans let the server re-plan your day when something changes. First, one test run of"
say "the morning task, from the server, with the token already stored there."
if confirm "Fire one test run now? (uses 1 of the routine's 30 fires an hour)"; then
  sql "select net.http_post(url := '$URL/functions/v1/routine-fire',
         headers := jsonb_build_object('x-sheet-cron',
           (select decrypted_secret from vault.decrypted_secrets where name = 'sheet_cron_secret')),
         body := '{}'::jsonb) as id" >/dev/null
  say "Fired. Checking the answer in 10 seconds..."
  sleep 10
  RES=$(sql "select status_code as code from net._http_response order by created desc limit 1")
  say "  Server answered: ${RES:-nothing yet}"
  open_url "https://claude.ai/code/routines/trig_011M52jmViV3VFUuYG7o2kg2"
  step "You should see one new run, started now. 200 above means it went."
else
  SKIPPED+=("Routine test fire, then turn replans on")
fi
pause

# ── 12 ───────────────────────────────────────────────────────────────────
stage "/plan: turn replans on"
open_url "$PLAN"
step "••• → Settings → Replans → turn them on."
note "Leave them off if the test run in the last stage didn't show up."
pause "Press Enter when done"

# ── 13 ───────────────────────────────────────────────────────────────────
stage "/plan: your day's settings"
step "Still in Settings:"
step "Workload cap: hours of planned work a day (6 by default). Save."
step "Habits: add each one (gym, lunch...) with its days, ideal time, minutes, flex and"
say "    Firm (always placed first) or Flexible."
step "Enrollment: when your SOLAR window opens, if you know it."
step "Triage rules: an address or domain to always or never put in Needs you."
note "All of these can change any time; the next plan uses them."
pause "Press Enter when done"

# ── 14 ───────────────────────────────────────────────────────────────────
stage "The live check"
say "Read-only. ✓ is good; ! is a source you haven't connected; ✗ is a problem."
note "Jobs run on their schedule, so a fresh source shows \"no sync yet\" for up to an hour."
pause "Press Enter to run it"
bash tools/verify-sheet-v5.sh 2>&1 | grep -E '^(✗|!)|All checks' || true
pause

finish
}

run_wizard "$@"; exit
